fn splitmix64(state: &mut u64) -> u64 {
    *state = state.wrapping_add(0x9e37_79b9_7f4a_7c15);
    let mut value = *state;
    value = (value ^ (value >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
    value = (value ^ (value >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
    value ^ (value >> 31)
}

fn generated_text(state: &mut u64) -> String {
    let length = (splitmix64(state) % 12) as usize;
    (0..length)
        .map(|_| match splitmix64(state) % 8 {
            0 => '\0',
            1 => '\u{1}',
            2 => 'é',
            3 => '🦀',
            _ => char::from(b'a' + (splitmix64(state) % 26) as u8),
        })
        .collect()
}

fn generated_scalar(state: &mut u64) -> Value {
    match splitmix64(state) % 6 {
        0 => Value::Null(ScalarType::Text),
        1 => Value::Bool(splitmix64(state) % 2 == 1),
        2 => Value::Int64(splitmix64(state) as i64),
        3 => {
            let value = f64::from_bits(splitmix64(state));
            Value::Float64(if value.is_finite() { value } else { 0.5 })
        }
        _ => Value::Text(generated_text(state)),
    }
}

/// Value identity under the codec contract: nulls match regardless of the
/// contextual scalar type, and floats compare by bit pattern after the
/// canonical `-0.0` to `+0.0` normalisation.
fn values_match(actual: &Value, expected: &Value) -> bool {
    match (actual, expected) {
        (Value::Null(_), Value::Null(_)) => true,
        (Value::Float64(actual), Value::Float64(expected)) => {
            let canonical = if *expected == 0.0 { 0.0 } else { *expected };
            actual.to_bits() == canonical.to_bits()
        }
        _ => actual == expected,
    }
}

/// Key encoding for one scalar, `None` for values the ordered key
/// layer cannot represent.
fn kv_encode(value: &Value) -> Option<Vec<u8>> {
    Some(match value {
        Value::Null(_) => rad::engine::kv::key_encoding::encode_null().to_vec(),
        Value::Bool(value) => rad::engine::kv::key_encoding::encode_bool(*value).to_vec(),
        Value::Int64(value) => rad::engine::kv::key_encoding::encode_i64(*value).to_vec(),
        Value::Float64(value) => rad::engine::kv::key_encoding::encode_f64(*value)?.to_vec(),
        Value::Text(value) => rad::engine::kv::key_encoding::encode_text(value),
    })
}

