#[test]
fn manifest_matches_the_normative_specification() {
    let text = std::fs::read(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/protocol/storage.keyform"
    ))
    .expect("read the normative specification");
    let digest = Sha256::digest(&text);
    let mut hex = String::with_capacity(64);
    for byte in digest {
        hex.push_str(&format!("{byte:02x}"));
    }
    assert_eq!(
        hex,
        rad::engine::kv::manifest::STORAGE_SPEC_SHA256,
        "specification changed without regeneration; run `task generate:storage`"
    );
    assert_eq!(rad::engine::kv::manifest::STORAGE_FORMAT_NAME, "storage");
    assert_eq!(rad::engine::kv::manifest::STORAGE_FORMAT_VERSION, 1);
}

