#[test]
fn uvarint_round_trip_for_seeded_samples() {
    let boundaries = [
        0_u64,
        1,
        127,
        128,
        255,
        16_383,
        16_384,
        u32::MAX as u64,
        u64::MAX >> 1,
        u64::MAX,
    ];
    let mut state = 0x6b65_7966_6f72_6d01_u64;
    let samples = boundaries
        .into_iter()
        .chain((0..4096).map(|_| splitmix64(&mut state)));
    for value in samples.collect::<Vec<_>>() {
        let mut encoded = Vec::new();
        rad::engine::exec::codec::append_uvarint(&mut encoded, value);
        let mut position = 0;
        assert_eq!(
            rad::engine::exec::codec::read_uvarint(&encoded, &mut position)
                .expect("encoded value decodes"),
            value
        );
        assert_eq!(position, encoded.len(), "self-delimiting for {value}");
    }
}

