#[test]
fn ordered_scalar_vectors() {
    assert_eq!(
        kv_encode(&Value::Null(ScalarType::Text)).expect("vector value encodes"),
        &[0x01]
    );
    assert_eq!(
        kv_encode(&Value::Bool(false)).expect("vector value encodes"),
        &[0x02, 0x00]
    );
    assert_eq!(
        kv_encode(&Value::Bool(true)).expect("vector value encodes"),
        &[0x02, 0x01]
    );
    assert_eq!(
        kv_encode(&Value::Int64(0_i64)).expect("vector value encodes"),
        &[0x03, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00]
    );
    // the key layer distinguishes the zero signs; the semantic layer above erases them
    assert_eq!(
        kv_encode(&Value::Float64(-0.0_f64)).expect("vector value encodes"),
        &[0x04, 0x7f, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff]
    );
    assert_eq!(
        kv_encode(&Value::Text("".into())).expect("vector value encodes"),
        &[0x05, 0x00, 0x01]
    );
    assert_eq!(
        kv_encode(&Value::Text("a\0b".into())).expect("vector value encodes"),
        &[0x05, 0x61, 0x00, 0xff, 0x62, 0x00, 0x01]
    );
    let ordered_0 = kv_encode(&Value::Null(ScalarType::Text)).expect("order vector encodes");
    let ordered_1 = kv_encode(&Value::Bool(false)).expect("order vector encodes");
    let ordered_2 = kv_encode(&Value::Bool(true)).expect("order vector encodes");
    assert!(ordered_0 < ordered_1, "order vector must ascend");
    assert!(ordered_1 < ordered_2, "order vector must ascend");
    let ordered_3 = kv_encode(&Value::Int64(-1_i64)).expect("order vector encodes");
    let ordered_4 = kv_encode(&Value::Int64(0_i64)).expect("order vector encodes");
    let ordered_5 = kv_encode(&Value::Int64(1_i64)).expect("order vector encodes");
    assert!(ordered_3 < ordered_4, "order vector must ascend");
    assert!(ordered_4 < ordered_5, "order vector must ascend");
    let ordered_6 = kv_encode(&Value::Float64(-0.0_f64)).expect("order vector encodes");
    let ordered_7 = kv_encode(&Value::Float64(0.0_f64)).expect("order vector encodes");
    assert!(ordered_6 < ordered_7, "order vector must ascend");
    let ordered_8 =
        kv_encode(&Value::Float64(-1.7976931348623157e308_f64)).expect("order vector encodes");
    let ordered_9 = kv_encode(&Value::Float64(-1.5_f64)).expect("order vector encodes");
    let ordered_10 = kv_encode(&Value::Float64(1.5_f64)).expect("order vector encodes");
    let ordered_11 =
        kv_encode(&Value::Float64(1.7976931348623157e308_f64)).expect("order vector encodes");
    assert!(ordered_8 < ordered_9, "order vector must ascend");
    assert!(ordered_9 < ordered_10, "order vector must ascend");
    assert!(ordered_10 < ordered_11, "order vector must ascend");
    let ordered_12 = kv_encode(&Value::Text("".into())).expect("order vector encodes");
    let ordered_13 = kv_encode(&Value::Text("a".into())).expect("order vector encodes");
    let ordered_14 = kv_encode(&Value::Text("a\0".into())).expect("order vector encodes");
    let ordered_15 = kv_encode(&Value::Text("a\0b".into())).expect("order vector encodes");
    let ordered_16 = kv_encode(&Value::Text("app".into())).expect("order vector encodes");
    let ordered_17 = kv_encode(&Value::Text("apple".into())).expect("order vector encodes");
    let ordered_18 = kv_encode(&Value::Text("b".into())).expect("order vector encodes");
    assert!(ordered_12 < ordered_13, "order vector must ascend");
    assert!(ordered_13 < ordered_14, "order vector must ascend");
    assert!(ordered_14 < ordered_15, "order vector must ascend");
    assert!(ordered_15 < ordered_16, "order vector must ascend");
    assert!(ordered_16 < ordered_17, "order vector must ascend");
    assert!(ordered_17 < ordered_18, "order vector must ascend");
    let ordered_19 = kv_encode(&Value::Null(ScalarType::Text)).expect("order vector encodes");
    let ordered_20 = kv_encode(&Value::Bool(false)).expect("order vector encodes");
    let ordered_21 =
        kv_encode(&Value::Int64(9223372036854775807_i64)).expect("order vector encodes");
    let ordered_22 =
        kv_encode(&Value::Float64(-1.7976931348623157e308_f64)).expect("order vector encodes");
    let ordered_23 = kv_encode(&Value::Text("".into())).expect("order vector encodes");
    assert!(ordered_19 < ordered_20, "order vector must ascend");
    assert!(ordered_20 < ordered_21, "order vector must ascend");
    assert!(ordered_21 < ordered_22, "order vector must ascend");
    assert!(ordered_22 < ordered_23, "order vector must ascend");
}

#[test]
fn ordered_scalar_order_preserving_for_seeded_samples() {
    let mut state = 0x6b65_7966_6f72_6d07_u64;
    for _ in 0..4096 {
        let (left, right) = (splitmix64(&mut state) as i64, splitmix64(&mut state) as i64);
        assert_eq!(
            kv_encode(&Value::Int64(left))
                .expect("int64 encodes")
                .cmp(&kv_encode(&Value::Int64(right)).expect("int64 encodes")),
            left.cmp(&right),
            "int64 ordering mismatch for {left} and {right}"
        );
        let (left, right) = (
            f64::from_bits(splitmix64(&mut state)),
            f64::from_bits(splitmix64(&mut state)),
        );
        if !left.is_nan() && !right.is_nan() {
            assert_eq!(
                kv_encode(&Value::Float64(left))
                    .expect("non-NaN float64 encodes")
                    .cmp(&kv_encode(&Value::Float64(right)).expect("non-NaN float64 encodes")),
                left.total_cmp(&right),
                "float64 ordering mismatch for {left:?} and {right:?}"
            );
        }
    }
}

