#[test]
fn catalog_transition_key_vectors() {
    let key = rad::engine::kv::keys::catalog_transition_key(5);
    assert_eq!(key, &[0x72, 0x37, 0x1a, 0x05]);
    let parts = rad::engine::kv::keys::decode_catalog_transition_key(&key).expect("vector decodes");
    assert_eq!(parts.transition, 5);
    assert!(rad::engine::exec::key_describe::describe_key(&key).is_some());
}

