#[test]
fn catalog_transition_unique_claim_key_vectors() {
    let key = rad::engine::kv::keys::catalog_transition_unique_claim_key(
        5,
        &[0x03, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x07],
        &[0x05, 0x61, 0x00, 0x01],
    );
    assert_eq!(
        key,
        &[
            0x72, 0x37, 0x1e, 0x05, 0x09, 0x03, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x07,
            0x05, 0x61, 0x00, 0x01
        ]
    );
    let parts = rad::engine::kv::keys::decode_catalog_transition_unique_claim_key(&key)
        .expect("vector decodes");
    assert_eq!(parts.transition, 5);
    assert_eq!(
        parts.indexed,
        vec![0x03, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x07]
    );
    assert_eq!(parts.primary_key, vec![0x05, 0x61, 0x00, 0x01]);
    assert!(rad::engine::exec::key_describe::describe_key(&key).is_some());
}

