#[test]
fn prefix_scan_bounds_are_smallest_and_exclusive() {
    assert_eq!(
        rad::engine::kv::key_encoding::prefix_end(&[0x01]),
        Some(vec![0x02])
    );
    assert_eq!(
        rad::engine::kv::key_encoding::prefix_end(&[0x61, 0x62, 0xff]),
        Some(vec![0x61, 0x63])
    );
    assert_eq!(
        rad::engine::kv::key_encoding::prefix_end(&[0xab, 0xcd]),
        Some(vec![0xab, 0xce])
    );
    assert_eq!(rad::engine::kv::key_encoding::prefix_end(&[0xff]), None);
    assert_eq!(rad::engine::kv::key_encoding::prefix_end(&[]), None);
    let mut state = 0x6b65_7966_6f72_6d0a_u64;
    for _ in 0..2048 {
        let length = 1 + (splitmix64(&mut state) % 6) as usize;
        let prefix: Vec<u8> = (0..length).map(|_| splitmix64(&mut state) as u8).collect();
        match rad::engine::kv::key_encoding::prefix_end(&prefix) {
            Some(end) => {
                assert!(prefix < end);
                assert!(end.len() <= prefix.len());
                for suffix in [&[][..], &[0x00][..], &[0xff][..], &[0xff, 0xff][..]] {
                    let mut key = prefix.clone();
                    key.extend_from_slice(suffix);
                    assert!(key < end, "suffixed key must stay under the bound");
                }
            }
            None => assert!(prefix.iter().all(|byte| *byte == 0xff)),
        }
    }
}
